script:
function setupList() {
    return {
        actions: [{
            label: __('CSKH'),
            onClick: () => window.location.assign('/cskh'),
        }],
    }
}

function setupForm({ doc }) {
    return {
        actions: [{
            label: __('Care workspace'),
            onClick: () => window.location.assign('/cskh/work-item?lead=' + encodeURIComponent((doc && doc.name) || '')),
        }],
    }
}
